import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cumprod_kernel_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void cumprod_kernel(const float* input, float* output, int dim_size, int batch_size) {
    const int batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    extern __shared__ float shared_buffer[];
    const int tid = threadIdx.x;

    // Cooperative load into shared memory
    for (int i = tid; i < dim_size; i += blockDim.x) {
        shared_buffer[i] = input[batch_idx * dim_size + i];
    }
    __syncthreads();

    // Sequential cumulative product by first thread
    if (tid == 0) {
        float acc = 1.0f;
        for (int i = 0; i < dim_size; ++i) {
            acc *= shared_buffer[i];
            shared_buffer[i] = acc;
        }
    }
    __syncthreads();

    // Store results
    for (int i = tid; i < dim_size; i += blockDim.x) {
        output[batch_idx * dim_size + i] = shared_buffer[i];
    }
}

torch::Tensor cumprod_cuda(torch::Tensor input, int dim) {
    TORCH_CHECK(input.dim() == 2, "Input must be 2D");
    TORCH_CHECK(dim == 1, "Only dim=1 supported");

    const auto batch_size = input.size(0);
    const auto dim_size = input.size(1);
    auto output = torch::empty_like(input);

    const int threads = 256;
    const size_t shared_mem = dim_size * sizeof(float);

    cumprod_kernel<<<batch_size, threads, shared_mem>>>(
        input.contiguous().data_ptr<float>(),
        output.data_ptr<float>(),
        dim_size,
        batch_size
    );

    return output;
}
"""

cumprod_cpp_source = "torch::Tensor cumprod_cuda(torch::Tensor input, int dim);"

cumprod_ext = load_inline(
    name='cumprod_ext',
    cpp_sources=cumprod_cpp_source,
    cuda_sources=cumprod_kernel_source,
    functions=['cumprod_cuda'],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, dim):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x):
        return cumprod_ext.cumprod_cuda(x, self.dim)
